javas.java:

int def ageLevel(int:stockAgeDays) {
    if (stockAgeDays >= 180) {
        return 4;
    } else if (stockAgeDays >= 90) {
        return 3;
    } else if (stockAgeDays >= 60) {
        return 2;
    } else if (stockAgeDays >= 30) {
        return 1;
    } else {
        return 0;
    }
}


double def baseDiscount(int:stockAgeDays) {
    if (stockAgeDays >= 180) {
        return 0.5;
    } else if (stockAgeDays >= 90) {
        return 0.65;
    } else if (stockAgeDays >= 60) {
        return 0.8;
    } else if (stockAgeDays >= 30) {
        return 0.9;
    } else {
        return 1.0;
    }
}


double def slowMovingFactor(int:recentSalesQty30d, int:stockQty) {
    if (stockQty <= 0) {
        return 0.0;
    }
    if (recentSalesQty30d * 10 <= stockQty) {
        return -0.15;
    } else if (recentSalesQty30d * 10 <= stockQty * 3) {
        return -0.08;
    } else if (recentSalesQty30d * 10 <= stockQty * 6) {
        return 0.0;
    } else {
        return 0.05;
    }
}


double def seasonFactor(str:seasonFactor) {
    if (seasonFactor == "OFF") {
        return -0.05;
    } else if (seasonFactor == "PEAK") {
        return 0.05;
    } else {
        return 0.0;
    }
}


double def perishableFactor(boolean:perishable, int:stockAgeDays) {
    if (perishable && stockAgeDays >= 7) {
        return -0.10;
    } else if (perishable) {
        return -0.05;
    } else {
        return 0.0;
    }
}


double def warehouseFactor(str:warehouseType) {
    if (warehouseType == "OUTSOURCE") {
        return -0.03;
    } else {
        return 0.0;
    }
}


double def applyFloor(double:price, double:costPrice, double:marginFloor) {
    double floor = costPrice * (1.0 + marginFloor);
    if (price < floor) {
        return floor;
    } else {
        return price;
    }
}


str def clearanceLevel(double:finalDiscount) {
    if (finalDiscount <= 0.55) {
        return "DEEP";
    } else if (finalDiscount <= 0.75) {
        return "MEDIUM";
    } else if (finalDiscount < 1.0) {
        return "LIGHT";
    } else {
        return "NONE";
    }
}


str def promotionType(str:clearanceLevel, boolean:perishable) {
    if (clearanceLevel == "DEEP" && perishable) {
        return "FLASH_SALE";
    } else if (clearanceLevel == "DEEP") {
        return "BUNDLE";
    } else if (clearanceLevel == "MEDIUM") {
        return "COUPON";
    } else if (clearanceLevel == "LIGHT") {
        return "MEMBER_PRICE";
    } else {
        return "NONE";
    }
}


boolean def needClearance(int:stockAgeDays, int:stockQty, int:recentSalesQty30d) {
    if (stockAgeDays >= 90) {
        return true;
    } else if (stockAgeDays >= 60 && recentSalesQty30d * 4 < stockQty) {
        return true;
    } else {
        return false;
    }
}
